<?php require __DIR__.'/../../bootstrap/app.php';role_required('admin');$db=Database::get();
$M=['cash'=>'Cash','bank_transfer'=>'Bank transfer','mobile_money'=>'Mobile money'];
function wallet(PDO $db,int $t,string $col,float $d):void{$db->prepare("INSERT INTO technician_wallets(technician_id,$col) VALUES(?,?) ON DUPLICATE KEY UPDATE $col=$col+VALUES($col)")->execute([$t,$d]);}
function wtx(PDO $db,int $t,string $type,float $amt,string $st):void{$db->prepare("INSERT INTO wallet_transactions(technician_id,transaction_type,amount,status) VALUES(?,?,?,?)")->execute([$t,$type,$amt,$st]);}
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$a=$_POST['action']??'';$id=(int)($_POST['id']??0);
 try{
 if($a==='record'){$amt=trim((string)($_POST['amount']??''));$m=$_POST['method']??'';$ref=mb_substr(trim((string)($_POST['reference']??'')),0,190);
  if(!is_numeric($amt)||$amt<=0||!isset($M[$m]))throw new RuntimeException('Enter an amount above 0 and a payment method.');
  $q=$db->prepare("SELECT sr.id,sr.customer_id,s.category_id,a.technician_id FROM service_requests sr JOIN services s ON s.id=sr.service_id JOIN service_assignments a ON a.id=(SELECT MAX(id) FROM service_assignments WHERE request_id=sr.id AND status NOT IN('rejected','cancelled')) LEFT JOIN payments p ON p.request_id=sr.id WHERE sr.id=? AND sr.status IN('in_progress','completed') AND p.id IS NULL");$q->execute([$id]);$r=$q->fetch();
  if(!$r)throw new RuntimeException('This request is not eligible, or a payment is already recorded.');
  $rate=commission_rate($db,(int)$r['technician_id'],(int)$r['category_id']);if($rate===null)throw new RuntimeException('Set a default commission rate first.');
  $co=round($amt*$rate/100,2);$te=round($amt-$co,2);
  $db->beginTransaction();$db->prepare("INSERT INTO payments(request_id,customer_id,provider,provider_reference,amount,status,idempotency_key,verified_at) VALUES(?,?,?,?,?,'successful',?,NOW())")->execute([$id,$r['customer_id'],$m,$ref,$amt,'manual-req-'.$id]);$pid=(int)$db->lastInsertId();
  $db->prepare("INSERT INTO commission_transactions(payment_id,technician_id,gross_amount,rate_snapshot,company_amount,technician_amount,status) VALUES(?,?,?,?,?,?,'pending')")->execute([$pid,$r['technician_id'],$amt,$rate,$co,$te]);
  wallet($db,(int)$r['technician_id'],'pending_balance',$te);wtx($db,(int)$r['technician_id'],'commission_pending',$te,'pending');$db->commit();audit('record payment','payment',$pid,['amount'=>$amt,'rate'=>$rate]);notice("Payment recorded. Company commission $co ETB ($rate%), technician $te ETB (pending release).");}
 elseif($a==='release'||$a==='editrate'){$c=$db->prepare("SELECT * FROM commission_transactions WHERE id=? AND status='pending'");$c->execute([$id]);$c=$c->fetch();if(!$c)throw new RuntimeException('Only pending commissions can be changed.');$t=(int)$c['technician_id'];
  $db->beginTransaction();
  if($a==='release'){$db->prepare("UPDATE commission_transactions SET status='released' WHERE id=?")->execute([$id]);wallet($db,$t,'pending_balance',-(float)$c['technician_amount']);wallet($db,$t,'available_balance',(float)$c['technician_amount']);wtx($db,$t,'commission_released',(float)$c['technician_amount'],'completed');audit('release commission','commission_tx',$id);notice('Released to the technician wallet.');}
  else{$rate=trim((string)($_POST['rate']??''));if(!is_numeric($rate)||$rate<0||$rate>100)throw new RuntimeException('Enter a rate between 0 and 100.');
   $co=round($c['gross_amount']*$rate/100,2);$te=round($c['gross_amount']-$co,2);$d=$te-(float)$c['technician_amount'];
   $db->prepare("UPDATE commission_transactions SET rate_snapshot=?,company_amount=?,technician_amount=? WHERE id=?")->execute([$rate,$co,$te,$id]);wallet($db,$t,'pending_balance',$d);wtx($db,$t,'commission_adjusted',$d,'pending');audit('edit commission rate','commission_tx',$id,['rate'=>$rate]);notice("Commission changed to $rate%. Company $co ETB, technician $te ETB.");}
  $db->commit();}
 }catch(RuntimeException $x){if($db->inTransaction())$db->rollBack();notice($x->getMessage());}
 catch(PDOException $x){if($db->inTransaction())$db->rollBack();notice($x->getCode()==='23000'?'A payment for this request already exists.':'Database error: nothing was saved.');}
 go('admin/payments.php');}
$elig=$db->query("SELECT sr.id,s.name sname,u.name cname,t.name tname,sr.status FROM service_requests sr JOIN services s ON s.id=sr.service_id JOIN users u ON u.id=sr.customer_id JOIN service_assignments a ON a.id=(SELECT MAX(id) FROM service_assignments WHERE request_id=sr.id AND status NOT IN('rejected','cancelled')) JOIN users t ON t.id=a.technician_id LEFT JOIN payments p ON p.request_id=sr.id WHERE sr.status IN('in_progress','completed') AND p.id IS NULL ORDER BY sr.id DESC")->fetchAll();
$tx=$db->query("SELECT ct.id,ct.gross_amount,ct.rate_snapshot,ct.company_amount,ct.technician_amount,ct.status,t.name tname,p.request_id,p.provider FROM commission_transactions ct JOIN payments p ON p.id=ct.payment_id JOIN users t ON t.id=ct.technician_id ORDER BY ct.id DESC LIMIT 100")->fetchAll();
$tot=$db->query("SELECT COALESCE(SUM(gross_amount),0) g,COALESCE(SUM(company_amount),0) c FROM commission_transactions WHERE status<>'reversed'")->fetch();
$title='Payments';require __DIR__.'/../../app/Views/header.php';?><section class="section"><div class="container"><div class="dash"><?php require __DIR__.'/../../app/Views/admin_nav.php';?><div><h1>Payments and commission</h1><p>Total recorded: <b><?=e($tot['g'])?> ETB</b> · Company commission: <b><?=e($tot['c'])?> ETB</b>. Payments here are recorded by the admin after money is received; there is no online payment gateway connected.</p>
<h3>Record a payment</h3><?php if(!$elig):?><p>No eligible requests. A request needs an assigned technician and status In progress or Completed, with no payment yet.</p><?php endif;?>
<?php foreach($elig as $r):?><form method="post" class="cardx mb-2 row g-2 align-items-center"><?=csrf_field()?><input type="hidden" name="action" value="record"><input type="hidden" name="id" value="<?=(int)$r['id']?>"><div class="col-md-4"><b>#<?=(int)$r['id']?> <?=e($r['sname'])?></b><br><small><?=e($r['cname'])?> → <?=e($r['tname'])?> (<?=e($r['status'])?>)</small></div><div class="col-md-2"><input class="form-control" name="amount" placeholder="Amount ETB" required></div><div class="col-md-2"><select class="form-select" name="method"><?php foreach($M as $k=>$l):?><option value="<?=e($k)?>"><?=e($l)?></option><?php endforeach;?></select></div><div class="col-md-2"><input class="form-control" name="reference" placeholder="Reference"></div><div class="col-md-2"><button class="btn btn-dark w-100">Record</button></div></form><?php endforeach;?>
<h3 class="mt-4">Commissions</h3><div class="table-responsive"><table class="table"><tr><th>Request</th><th>Technician</th><th>Gross</th><th>Rate</th><th>Company</th><th>Technician gets</th><th>Status</th><th>Actions</th></tr><?php foreach($tx as $r):?><tr><td>#<?=(int)$r['request_id']?></td><td><?=e($r['tname'])?></td><td><?=e($r['gross_amount'])?></td><td><?=e($r['rate_snapshot'])?>%</td><td><?=e($r['company_amount'])?></td><td><?=e($r['technician_amount'])?></td><td><?=e($r['status'])?></td><td><?php if($r['status']==='pending'):?><form method="post" class="d-flex gap-1"><?=csrf_field()?><input type="hidden" name="id" value="<?=(int)$r['id']?>"><input class="form-control form-control-sm" style="width:80px" name="rate" value="<?=e($r['rate_snapshot'])?>"><button name="action" value="editrate" class="btn btn-sm btn-outline-dark">Edit %</button><button name="action" value="release" class="btn btn-sm btn-success">Release</button></form><?php else:?>Locked<?php endif;?></td></tr><?php endforeach;?></table></div></div></div></div></section><?php require __DIR__.'/../../app/Views/footer.php';?>